// Vérification de la signature HMAC-SHA256 (en-tête X-MAJI-Signature).
// REMPLACER LA VALEUR DU SECRET par celle du site (via `wp option get maji_webhook_secret`).
const crypto = require('crypto');
const SECRET = 'REMPLACER_PAR_LE_SECRET_DU_SITE';
const body = JSON.stringify($input.first().json.body);
const signature = $input.first().json.headers['x-maji-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(body).digest('hex');
if (signature !== expected) {
  throw new Error('Signature invalide — webhook rejeté');
}
return [{ json: $input.first().json.body }];

// Message au client selon le nouveau statut (uniquement avec consentement).
const p = $input.first().json;
const isOrder = p.event.startsWith('order.');
const entity = isOrder ? p.order : p.reservation;
if (!entity.customer.whatsapp_consent) {
  return []; // pas de consentement, pas de message
}
const labels = {
  confirmed: 'confirmée ✅', declined: 'refusée ❌', cancelled: 'annulée',
  processing: 'en préparation 👨‍🍳', completed: 'livrée / terminée ✅', cancelled_order: 'annulée'
};
const quoi = isOrder ? `votre commande n°${entity.number}` : `votre demande de réservation`;
const statut = labels[p.new_status] || p.new_status;
const text = `Bonjour ${entity.customer.name},\n${quoi} est maintenant : ${statut}.\nMerci de votre confiance !`;
return [{ json: { text, phone: entity.customer.phone } }];
